<?php require_once __DIR__.'/../config.php';require_admin();$id=(int)($_GET['id']??0);$s=db()->prepare('SELECT document FROM applications WHERE id=?');$s->execute([$id]);$a=$s->fetch();if(!$a||!$a['document']){http_response_code(404);exit('Document not found.');}$path=UPLOAD_DIR.basename($a['document']);if(!is_file($path)){http_response_code(404);exit('File not found.');}$ext=strtolower(pathinfo($path,PATHINFO_EXTENSION));$types=['pdf'=>'application/pdf','jpg'=>'image/jpeg','jpeg'=>'image/jpeg','png'=>'image/png'];header('Content-Type: '.($types[$ext]??'application/octet-stream'));header('Content-Disposition: inline; filename="'.basename($path).'"');readfile($path);
